# phases.sh <name>: phase marker times from the -vv log and RSS at/after them
d=/Users/gabe/Projects/caliper-fixtures/oracle-run/mem/runs
n=$1
sed 's/\x1b\[[0-9;]*m//g' $d/$n.log > $d/$n.clean
marks=$(awk '
 /opening it again/ && !a {print $1, "early-program-discarded"; a=1}
 /semantic program built/ && !b {print $1, "program-built"; b=1}
 /semantic component answered/ && !c {print $1, "first-component"; c=1}
 /semantic component answered/ {last=$1}
