awk '{ if ($1>=nx) {printf "%d:%d ", $1, $2; nx=$1+250} } END {print ""}' $d/$n.rss
rtk proxy grep -o -e 'peak rss: [0-9.]* [GM]iB, peak commit: [0-9.]* [GM]iB' $d/$n.clean
rtk proxy grep -o -e 'type_memo=[^ ]*' -e 'programs=[0-9]*' -e 'program_ms=[0-9]*' $d/$n.clean | sort | uniq -c

