    let (mut rss, mut peak, mut commit) = (0usize, 0usize, 0usize);
    let null = std::ptr::null_mut();
    unsafe { libmimalloc_sys::mi_process_info(null, null, null, &raw mut rss, &raw mut peak, &raw mut commit, null, null) };
    eprintln!("PHASE {name} rss={} peak={} commit={} arena={:?}", rss >> 20, peak >> 20, commit >> 20, checker::arena_mib());
}

/// SCRATCH: CAL_PROGRAMS overrides CHECKER_PROGRAMS.
fn programs_env() -> usize {
    std::env::var("CAL_PROGRAMS").ok().and_then(|v| v.parse().ok()).unwrap_or(CHECKER_PROGRAMS)
}

/// SCRATCH: CAL_BATCHES=N answers the request in N sequential batches of root files, each with its own checker.
fn batched(request: SemanticRequest, n: usize) -> SemanticOutcome {
    let order: Vec<Utf8PathBuf> = group_by_file(&request).2.iter().map(|f| f.to_path_buf()).collect();
    let per = order.len().div_ceil(n).max(1);
    let mut all = SemanticOutcome::default();
    for (i, chunk) in order.chunks(per).enumerate() {
        let keep: rustc_hash::FxHashSet<&Utf8PathBuf> = chunk.iter().collect();
        let targets: Vec<Target> = request.targets.iter().filter(|t| keep.contains(&t.file_path)).cloned().collect();
        let mut sub = SemanticRequest::new(request.project_root.clone(), targets);
        sub.tsconfig = request.tsconfig.clone();
        sub.request_timeout = request.request_timeout;
        sub.reverse_queries = request.reverse_queries;
        let mut out = resolve_with(sub, None, None);
        all.components.append(&mut out.components);
        all.fallbacks.append(&mut out.fallbacks);
        all.diagnostics.append(&mut out.diagnostics);
        phase(&format!("batch-{i}-done"));
    }
    // targets of no exported file (not exported anywhere)
    let mut rest = SemanticRequest::new(request.project_root.clone(), request.targets.iter().filter(|t| t.exports.is_empty()).cloned().collect());
    rest.tsconfig = None;
    all.fallbacks.append(&mut group_by_file(&rest).0.fallbacks);
    all.components.sort_by(|a, b| a.key.cmp(&b.key));
    all.fallbacks.sort_by(|a, b| a.key.cmp(&b.key));
    all.fallbacks.dedup_by(|a, b| a.key == b.key);
    all
}
