#!/usr/bin/env python3
# same.py <a.json> <b.json>...: compare each b to a with `stats` dropped; count changed props (scratch).
import json, sys
def load(p):
    d = json.load(open(p)); d.pop('stats', None); return d
a = load(sys.argv[1])
def props(d):
    out = {}
    table = d.get('props') if isinstance(d.get('props'), list) else None
    for c in d.get('components', []):
        k = c.get('key') or c.get('name')
        for i, p in enumerate(c.get('props', [])):
            v = table[p] if isinstance(p, int) and table else p
            name = v.get('name') if isinstance(v, dict) else str(i)
            out[(k, name)] = json.dumps(v, sort_keys=True)
    return out
pa = None
for b in sys.argv[2:]:
    d = load(b)
    if d == a:
        print(f"{b.split('/')[-1]}: identical (stats dropped)"); continue
    pa = pa or props(a); pb = props(d)
    changed = [k for k in pa if k in pb and pa[k] != pb[k]]
    gone = [k for k in pa if k not in pb]; new = [k for k in pb if k not in pa]
    ca = {c.get('key') for c in a.get('components', [])}; cb = {c.get('key') for c in d.get('components', [])}
    print(f"{b.split('/')[-1]}: DIFFERS: props changed {len(changed)}, removed {len(gone)}, added {len(new)}, components {len(ca)}->{len(cb)}; top keys differing: {[k for k in a if a.get(k) != d.get(k)]}")
    for k in changed[:3]: print("   e.g.", k, pa[k][:160], "->", pb[k][:160])
    diags = [x.get('code') for x in d.get('diagnostics', [])]
    import collections; print("   diagnostics:", collections.Counter(diags).most_common(4))

